1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {ListSessionsMessage, OutgoingMessage} from '../../types/messages.js';
6	import type {SessionStore} from '../../types/sessionStore.js';
7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
8	import {validateMessage} from './validation.js';
9	import type {ValidationResult} from './validation.js';
10	import {PerSessionLock} from '../../shared/perSessionLock.js';
11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {
22	  sendJson,
23	  sendUpsert,
24	  sendDelta,
25	  sendCommit,
26	  sendSkip,
27	  sendError,
28	  sendSessionList,
29	  sendStreamEnd,
30	} from './sender.js';
31	import {log} from '../../shared/logger.js';
32	
33	interface StreamState {
34	  thinkingIndex: number | null;
35	  assistantIndex: number | null;
36	  suppressOutput: boolean;
37	  sentAssistantIndices: number[];
38	}
39	
40	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
41	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
42	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
43	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
44	  const lock = new PerSessionLock();
45	  return function handleMessage(
46	    ws: WebSocket,
47	    session: ChatSession,
48	    rawMessage: unknown,
49	    signal?: AbortSignal
50	  ): Promise<void> {
51	    const validation = validateMessage(rawMessage);
52	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
53	    if (isUserMessageFrame(rawMessage)) {
54	      return lock.run(session.sessionId, () =>
55	        answerInTurn(ws, session, orchestrator, validation, signal, sessionStore)
56	      );
57	    }
58	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
59	    return wsErrorHandler(ws, async () => answerFrame(ws, session, validation, sessionStore));
60	  };
61	}
62	
63	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
64	async function answerInTurn(
65	  ws: WebSocket,
66	  session: ChatSession,
67	  orchestrator: ChatOrchestrator,
68	  validation: ValidationResult,
69	  signal: AbortSignal | undefined,
70	  sessionStore: SessionStore | undefined
71	): Promise<void> {
72	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
73	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
74	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
75	    return;
76	  }
77	  const startedAt = Date.now();
78	  try {
79	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal, sessionStore));
80	  } finally {
81	    endTurn(ws, session, signal, startedAt);
82	  }
83	}
84	
85	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
86	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
87	  if (signal?.aborted) {
88	    log.info('message', 'turn abandoned: its socket closed', {
89	      sessionId: session.sessionId,
90	      elapsedMs: Date.now() - startedAt,
91	    });
92	    return;
93	  }
94	  sendStreamEnd(ws);
95	}
96	
97	async function answerUserMessage(
98	  ws: WebSocket,
99	  session: ChatSession,
100	  orchestrator: ChatOrchestrator,
101	  validation: ValidationResult,
102	  signal: AbortSignal | undefined,
103	  sessionStore: SessionStore | undefined
104	): Promise<void> {
105	  const message = validation.valid ? validation.data : undefined;
106	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
107	  await answerFrame(ws, session, validation, sessionStore);
108	}
109	
110	async function answerFrame(
111	  ws: WebSocket,
112	  session: ChatSession,
113	  validation: ValidationResult,
114	  sessionStore: SessionStore | undefined
115	): Promise<void> {
116	  if (!validation.valid) {
117	    log.warn('message', 'validation failed', {error: validation.error});
118	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
119	    return;
120	  }
121	
122	  const message = validation.data;
123	  if (message.type === 'ping') handlePing(ws, message.timestamp);
124	  if (message.type === 'list_sessions') await handleListSessions(ws, session, message, sessionStore);
125	}
126	
127	// Off the lock, because a list mutates nothing and must not queue behind a streaming turn. The user id is the
128	// connection's own, read from the session, so the frame never names whose conversations it gets.
129	async function handleListSessions(
130	  ws: WebSocket,
131	  session: ChatSession,
132	  message: ListSessionsMessage,
133	  sessionStore: SessionStore | undefined
134	): Promise<void> {
135	  try {
136	    sendSessionList(
137	      ws,
138	      (await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before})) ?? []
139	    );
140	  } catch (error) {
141	    const detail = error instanceof Error ? error.message : 'Unknown error';
142	    log.error('ws', 'session list failed', {userId: session.userId, error: detail});
143	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list conversations');
144	  }
145	}
146	
147	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
148	function isUserMessageFrame(rawMessage: unknown): boolean {
149	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
150	}
151	
152	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
153	  try {
154	    await action();
155	  } catch (error) {
156	    const message = error instanceof Error ? error.message : 'Unknown error';
157	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
158	    log.error('message', 'handling error', {error: message, code});
159	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
160	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
161	      return;
162	    }
163	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
164	  }
165	}
166	
167	async function handleUserMessage(
168	  ws: WebSocket,
169	  session: ChatSession,
170	  orchestrator: ChatOrchestrator,
171	  content: string,
172	  signal: AbortSignal | undefined
173	): Promise<void> {
174	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
175	
176	  const userEntry = createUserEntry(content);
177	  const userIndex = appendEntry(session, userEntry);
178	  sendUpsert(ws, userIndex, userEntry);
179	
180	  const parser = new ThinkingTagParser();
181	  const state: StreamState = {
182	    thinkingIndex: null,
183	    assistantIndex: null,
184	    suppressOutput: false,
185	    sentAssistantIndices: [],
186	  };
187	
188	  let textChunkCount = 0;
189	
190	  try {
191	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
192	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
193	      if (signal?.aborted) break;
194	      textChunkCount = logChunk(chunk, textChunkCount);
195	      processChunk(ws, session, state, parser, chunk);
196	    }
197	  } finally {
198	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
199	    flushHeldText(ws, session, state, parser);
200	    closeCutOff(ws, session, state, 'thinkingIndex');
201	    closeCutOff(ws, session, state, 'assistantIndex');
202	  }
203	
204	  if (textChunkCount > 0) {
205	    log.debug('stream', `received ${textChunkCount} text chunks`);
206	  }
207	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
208	}
209	
210	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
211	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
212	  if (chunk.type === 'text') return textChunkCount + 1;
213	
214	  if (textChunkCount > 0) {
215	    log.debug('stream', `received ${textChunkCount} text chunks`);
216	  }
217	
218	  if (chunk.type === 'tool_result') {
219	    log.debug('stream', 'tool_result chunk', {
220	      messageCount: chunk.clientMessages.length,
221	      types: chunk.clientMessages.map(m => m.type),
222	    });
223	    return 0;
224	  }
225	
226	  log.debug('stream', 'chunk', {type: chunk.type});
227	  return 0;
228	}
229	
230	function processChunk(
231	  ws: WebSocket,
232	  session: ChatSession,
233	  state: StreamState,
234	  parser: ThinkingTagParser,
235	  chunk: MessageChunk
236	): void {
237	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
238	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
239	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
240	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
241	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
242	}
243	
244	function processTextChunk(
245	  ws: WebSocket,
246	  session: ChatSession,
247	  state: StreamState,
248	  parser: ThinkingTagParser,
249	  text: string
250	): void {
251	  const segments = parser.push(text);
252	  for (const segment of segments) {
253	    handleTextSegment(ws, session, state, segment);
254	  }
255	}
256	
257	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
258	  if (segment.type === 'thinking') {
259	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
260	    return;
261	  }
262	  commitAndClear(ws, session, state, 'thinkingIndex');
263	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
264	}
265	
266	function streamSegment(
267	  ws: WebSocket,
268	  session: ChatSession,
269	  state: StreamState,
270	  key: StateIndexKey,
271	  createEntry: EntryFactory,
272	  content: string
273	): void {
274	  const isNew = initSegment(session, state, key, createEntry);
275	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
276	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
277	  appendDelta(session, state[key]!, content);
278	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
279	}
280	
281	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
282	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
283	  markSuppressed(session, index);
284	  sendSkip(ws, index);
285	}
286	
287	function markSuppressed(session: ChatSession, index: number): void {
288	  const entry = session.entries[index];
289	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
290	}
291	
292	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
293	  if (state[key] !== null) return false;
294	  state[key] = appendEntry(session, createEntry());
295	  return true;
296	}
297	
298	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
299	  const index = state[key];
300	  if (index === null) return;
301	
302	  commitEntry(session, index);
303	  state[key] = null;
304	
305	  // Only what the client received can be retracted, and only assistant entries.
306	  if (state.suppressOutput) return;
307	
308	  sendCommit(ws, index);
309	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
310	}
311	
312	function processToolUseChunk(
313	  ws: WebSocket,
314	  session: ChatSession,
315	  toolCall: {name: string; input: Record<string, unknown>}
316	): void {
317	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
318	  const toolIndex = appendEntry(session, toolEntry);
319	  sendUpsert(ws, toolIndex, toolEntry);
320	}
321	
322	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
323	  for (const msg of clientMessages) {
324	    log.debug('stream', 'forwarding client message to frontend', {
325	      type: msg.type,
326	      index: 'index' in msg ? msg.index : undefined,
327	    });
328	    sendJson(ws, msg);
329	  }
330	}
331	
332	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
333	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
334	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
335	  commitOpenEntries(ws, session, state);
336	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
337	
338	  for (const idx of state.sentAssistantIndices) {
339	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
340	    markSuppressed(session, idx);
341	  }
342	
343	  state.sentAssistantIndices = [];
344	  state.suppressOutput = true;
345	}
346	
347	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
348	  flushHeldText(ws, session, state, parser);
349	  commitOpenEntries(ws, session, state);
350	}
351	
352	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
353	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
354	  for (const segment of parser.flush()) {
355	    handleTextSegment(ws, session, state, segment);
356	  }
357	}
358	
359	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
360	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
361	  const index = state[key];
362	  if (index === null) return;
363	  markTruncated(session, index);
364	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
365	  commitAndClear(ws, session, state, key);
366	}
367	
368	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
369	  commitAndClear(ws, session, state, 'thinkingIndex');
370	  commitAndClear(ws, session, state, 'assistantIndex');
371	}
372	
373	function handlePing(ws: WebSocket, timestamp: number): void {
374	  ws.send(JSON.stringify({type: 'pong', timestamp}));
375	}
