216	    auth.userId = 'u2';
217	
218	    const otherUser = await connectAndSettle(`${base}?sessionId=${first}`);
219	    const neverIssued = await connectAndSettle(`${base}?sessionId=${NEVER_ISSUED}`);
220	
221	    expect({fresh: otherUser[0].sessionId !== first, otherUser: shapeOf(otherUser)}).toEqual({
222	      fresh: true,
223	      otherUser: shapeOf(neverIssued),
224	    });
225	  });
226	
227	  it('answers a never-issued id with resumed false, resumeFailure unknown, and no replay or error', async () => {
228	    const {base} = await startEngine(new InMemorySessionStore(), RESUME_ON);
229	
230	    const frames = await connectAndSettle(`${base}?sessionId=${NEVER_ISSUED}`);
231	
232	    expect(shapeOf(frames)).toEqual({
233	      keys: ['examplePrompts', 'message', 'resumeFailure', 'resumed', 'sessionId', 'type'],
234	      resumed: false,
235	      resumeFailure: 'unknown',
236	      types: ['connected', 'pong'],
237	    });
238	  });
239	
240	  it('never adopts a requested id as a key: one session, under the id the server minted', async () => {
241	    const store = new InMemorySessionStore();
242	    const {base} = await startEngine(store, RESUME_ON);
243	
244	    const frames = await connectAndSettle(`${base}?sessionId=${NEVER_ISSUED}`);
245	
246	    expect({
247	      held: await store.count(),
248	      adopted: (await store.get(NEVER_ISSUED)) !== undefined,
249	      minted: (await store.get(frames[0].sessionId ?? '')) !== undefined,
250	    }).toEqual({held: 1, adopted: false, minted: true});
251	  });
252	
253	  it('still calls onDisconnect with the session id when a socket closes under resume', async () => {
254	    const {disconnected, base} = await startEngine(new InMemorySessionStore(), RESUME_ON);
255	
256	    const first = await firstTurn(base);
257	    await eventually(() => disconnected.length > 0);
258	
259	    expect(disconnected).toEqual([first]);
260	  });
261	
262	  it('keeps the credentials of the socket that resumed a session when the socket it replaced closes', async () => {
263	    const store = new InMemorySessionStore();
264	    const {base, disconnected, firstServerClose} = await startEngine(store, RESUME_ON);
265	    const replaced = open(base, 'old');
266	    const [greeting] = (await once(replaced, 'message')) as [Buffer];
267	    const sessionId = (JSON.parse(String(greeting)) as Frame).sessionId ?? '';
268	
269	    const frames = await connectAndSettle(`${base}?sessionId=${sessionId}`, 'new');
270	    replaced.close();
271	    await firstServerClose;
272	
273	    const held = await store.get(sessionId);
274	    expect({resumed: frames[0].resumed, disconnected, authorization: held?.authHeaders?.authorization}).toEqual({
275	      resumed: true,
276	      disconnected: [sessionId],
277	      authorization: 'Bearer new',
278	    });
279	  });
280	
281	  it('gives a session back the credentials of a socket still open when the socket that resumed it closes', async () => {
282	    const store = new InMemorySessionStore();
283	    const {base} = await startEngine(store, RESUME_ON);
284	    const first = open(base, 'first');
285	    const [greeting] = (await once(first, 'message')) as [Buffer];
286	    const sessionId = (JSON.parse(String(greeting)) as Frame).sessionId ?? '';
287	    const second = open(`${base}?sessionId=${sessionId}`, 'second');
288	    await once(second, 'message');
289	    const held = await store.get(sessionId);
290	    const whileBothOpen = held?.authHeaders?.authorization;
291	
292	    second.close();
293	    await eventually(() => held?.authHeaders?.authorization !== whileBothOpen);
294	
295	    expect({whileBothOpen, afterSecondCloses: held?.authHeaders?.authorization}).toEqual({
296	      whileBothOpen: 'Bearer second',
297	      afterSecondCloses: 'Bearer first',
